import{_ as e,c as l,o as i,ae as o}from"./chunks/framework.DNEoaTf_.js";const c=JSON.parse('{"title":"トラブルシューティング","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/troubleshooting.md","filePath":"ja/guide/troubleshooting.md"}'),t={name:"ja/guide/troubleshooting.md"};function r(u,a,h,s,n,d){return i(),l("div",null,[...a[0]||(a[0]=[o('<h1 id="トラブルシューティング" tabindex="-1">トラブルシューティング <a class="header-anchor" href="#トラブルシューティング" aria-label="Permalink to &quot;トラブルシューティング&quot;">​</a></h1><h2 id="サムネイルが表示されない" tabindex="-1">サムネイルが表示されない <a class="header-anchor" href="#サムネイルが表示されない" aria-label="Permalink to &quot;サムネイルが表示されない&quot;">​</a></h2><h3 id="原因と対処法" tabindex="-1">原因と対処法 <a class="header-anchor" href="#原因と対処法" aria-label="Permalink to &quot;原因と対処法&quot;">​</a></h3><h4 id="youtube-の動画ページではない" tabindex="-1">YouTube の動画ページではない <a class="header-anchor" href="#youtube-の動画ページではない" aria-label="Permalink to &quot;YouTube の動画ページではない&quot;">​</a></h4><ul><li>拡張機能は YouTube の動画再生ページでのみ動作します</li><li>ホームページやチャンネルページでは使用できません</li></ul><h4 id="動画が読み込まれていない" tabindex="-1">動画が読み込まれていない <a class="header-anchor" href="#動画が読み込まれていない" aria-label="Permalink to &quot;動画が読み込まれていない&quot;">​</a></h4><ul><li>ページが完全に読み込まれるまで待ってください</li><li>ページを更新してみてください</li></ul><h4 id="拡張機能の権限が不足している" tabindex="-1">拡張機能の権限が不足している <a class="header-anchor" href="#拡張機能の権限が不足している" aria-label="Permalink to &quot;拡張機能の権限が不足している&quot;">​</a></h4><ol><li><code>chrome://extensions/</code> (Chrome) または <code>about:addons</code> (Firefox) を開く</li><li>YouTube Watch Thumbnails を見つける</li><li><strong>詳細</strong> をクリック</li><li>すべての権限が有効になっていることを確認</li></ol><h2 id="一部のサムネイルが表示されない" tabindex="-1">一部のサムネイルが表示されない <a class="header-anchor" href="#一部のサムネイルが表示されない" aria-label="Permalink to &quot;一部のサムネイルが表示されない&quot;">​</a></h2><h3 id="maxresdefault-が表示されない" tabindex="-1">maxresdefault が表示されない <a class="header-anchor" href="#maxresdefault-が表示されない" aria-label="Permalink to &quot;maxresdefault が表示されない&quot;">​</a></h3><ul><li>すべての動画で maxresdefault（最大画質）が利用可能とは限りません</li><li>YouTube が動画に対して高解像度サムネイルを生成していない場合があります</li><li>低解像度のサムネイル（hqdefault など）を使用してください</li></ul><h3 id="webp-形式が表示されない" tabindex="-1">WebP 形式が表示されない <a class="header-anchor" href="#webp-形式が表示されない" aria-label="Permalink to &quot;WebP 形式が表示されない&quot;">​</a></h3><ul><li>一部の動画では WebP 形式のサムネイルが提供されていない場合があります</li><li>JPG 形式を使用してください</li></ul><h2 id="ポップアップが開かない" tabindex="-1">ポップアップが開かない <a class="header-anchor" href="#ポップアップが開かない" aria-label="Permalink to &quot;ポップアップが開かない&quot;">​</a></h2><h3 id="確認事項" tabindex="-1">確認事項 <a class="header-anchor" href="#確認事項" aria-label="Permalink to &quot;確認事項&quot;">​</a></h3><ul><li>YouTube の動画ページで動画を再生しているか確認</li><li>ブラウザを再起動してみてください</li><li>拡張機能を無効化してから再度有効化</li></ul><h2 id="ダウンロードができない" tabindex="-1">ダウンロードができない <a class="header-anchor" href="#ダウンロードができない" aria-label="Permalink to &quot;ダウンロードができない&quot;">​</a></h2><h3 id="画像を保存できない" tabindex="-1">画像を保存できない <a class="header-anchor" href="#画像を保存できない" aria-label="Permalink to &quot;画像を保存できない&quot;">​</a></h3><ul><li>右クリックメニューから <strong>名前を付けて画像を保存</strong> を選択</li><li>または、画像をクリックして新しいタブで開き、そこから保存</li><li>ブラウザの設定でダウンロードが許可されているか確認</li></ul><h2 id="youtube-shorts-で動作しない" tabindex="-1">YouTube Shorts で動作しない <a class="header-anchor" href="#youtube-shorts-で動作しない" aria-label="Permalink to &quot;YouTube Shorts で動作しない&quot;">​</a></h2><h3 id="対処法" tabindex="-1">対処法 <a class="header-anchor" href="#対処法" aria-label="Permalink to &quot;対処法&quot;">​</a></h3><ul><li>Shorts ページで完全に動画が読み込まれるまで待つ</li><li>ページを更新してみる</li><li>通常の動画と同じ操作（ツールバーアイコンをクリック）を試す</li></ul><h2 id="それでも解決しない場合" tabindex="-1">それでも解決しない場合 <a class="header-anchor" href="#それでも解決しない場合" aria-label="Permalink to &quot;それでも解決しない場合&quot;">​</a></h2><p>以下の方法をお試しください：</p><ol><li><strong>拡張機能を再起動</strong>: 拡張機能を無効化してから再度有効化</li><li><strong>ブラウザを再起動</strong>: ブラウザを完全に終了してから再度開く</li><li><strong>拡張機能を再インストール</strong>: アンインストールしてから最新版を再度インストール</li><li><strong>ブラウザのキャッシュをクリア</strong>: ブラウザ設定からキャッシュを削除</li></ol><div class="tip custom-block"><p class="custom-block-title">サポート</p><p>上記で解決しない場合は、<a href="https://github.com/mosunset/youtube_watch_thumbnails/issues" target="_blank" rel="noreferrer">GitHub Issues</a> で報告してください。その際、以下の情報を含めてください：</p><ul><li>使用しているブラウザとバージョン</li><li>問題が発生した動画の URL</li><li>エラーメッセージ（もしあれば）</li></ul></div>',27)])])}const m=e(t,[["render",r]]);export{c as __pageData,m as default};
